"use client"
import { useRouter } from 'next/navigation';
import React, { useEffect } from 'react'

const MyOrderPage = () => {
    const jwt = sessionStorage.getItem("authToken");
    const router = useRouter();

    useEffect(()=>{
        if(!jwt){
            router.replace('/')
        }
    },[])
  return (
    <div className='flex  flex-col'>
        <div>

        </div>

    </div>
  )
}

export default MyOrderPage